import {
  batch,
  createStore,
  init,
  setup,
  subscribe,
  throwOnConflictingProps,
} from "@ariakit/store";
import type { Store, StoreOptions, StoreProps } from "@ariakit/store";
import {
  applyState,
  getDocument,
  sortBasedOnDOMPosition,
  chain,
  defaultValue,
} from "@ariakit/utils";
import type { BivariantCallback } from "@ariakit/utils";

function getCommonParent(items: CollectionStoreItem[]) {
  const firstItem = items.find((item) => !!item.element);
  const lastElement = [...items]
    .reverse()
    .find((item) => !!item.element)?.element;
  let parentElement = firstItem?.element?.parentElement;
  if (!lastElement) {
    return getDocument(parentElement).body;
  }
  while (parentElement) {
    const parent = parentElement;
    if (parent.contains(lastElement)) {
      return parentElement;
    }
    parentElement = parentElement.parentElement;
  }
  return getDocument(parentElement).body;
}

interface CollectionLookup<T extends CollectionStoreItem> {
  controlledItems: Map<string, T>;
  registeredItems: Map<string, T>;
  controlledItemsSource: T[];
  propagatedItems: T[];
}

interface CollectionPrivateStore<T extends CollectionStoreItem> extends Store<
  CollectionStoreState<T>
> {
  __unstableCollectionLookup: CollectionLookup<T>;
}

function getPrivateStore<T extends CollectionStoreItem>(
  store?: Store & {
    __unstablePrivateStore?: CollectionPrivateStore<T>;
  },
) {
  return store?.__unstablePrivateStore;
}

const itemIdCacheThreshold = 64;

interface ItemIdCache<T extends CollectionStoreItem> {
  items?: T[];
  ids?: Set<string>;
}

// Cache IDs only for large immutable state arrays so repeated registrations can
// skip O(n) absence scans. Replacing the array invalidates the cache. Existing
// IDs still use findIndex to preserve their position and previous value.
function getCachedItemIds<T extends CollectionStoreItem>(
  items: T[],
  cache: ItemIdCache<T>,
) {
  if (items.length < itemIdCacheThreshold) {
    if (cache.ids) {
      cache.items = undefined;
      cache.ids = undefined;
    }
    return;
  }
  if (cache.items === items) {
    return cache.ids;
  }
  const ids = new Set<string>();
  for (const item of items) {
    ids.add(item.id);
  }
  cache.items = items;
  cache.ids = ids;
  return ids;
}

function setCachedItemIds<T extends CollectionStoreItem>(
  items: T[],
  cache: ItemIdCache<T>,
  ids?: Set<string>,
) {
  if (items.length < itemIdCacheThreshold) {
    if (cache.ids) {
      cache.items = undefined;
      cache.ids = undefined;
    }
    return;
  }
  if (!ids) {
    ids = new Set<string>();
    for (const item of items) {
      ids.add(item.id);
    }
  }
  cache.items = items;
  cache.ids = ids;
}

/**
 * Creates a collection store.
 */
export function createCollectionStore<
  T extends CollectionStoreItem = CollectionStoreItem,
>(props: CollectionStoreProps<T> = {}): CollectionStore<T> {
  throwOnConflictingProps(props, props.store);

  const syncState = props.store?.getState();

  const items = defaultValue(
    props.items,
    syncState?.items,
    props.defaultItems,
    [],
  );

  const syncPrivateStore = getPrivateStore<T>(props.store);
  // Controlled items and registrations are shared by composed stores through
  // their private stores.
  const collectionLookup: CollectionLookup<T> =
    syncPrivateStore?.__unstableCollectionLookup ?? {
      controlledItems: new Map(items.map((item) => [item.id, item])),
      registeredItems: new Map(),
      controlledItemsSource: items,
      propagatedItems: items,
    };
  const { controlledItems, registeredItems } = collectionLookup;
  // These arrays are replaced independently, so each needs its own cache.
  const itemIdCache: ItemIdCache<T> = {};
  const renderedItemIdCache: ItemIdCache<T> = {};

  const initialState: CollectionStoreState<T> = {
    items,
    renderedItems: defaultValue(syncState?.renderedItems, []),
  };

  const collection = createStore(initialState, props.store);

  const privateStore = Object.assign(
    createStore(
      { items, renderedItems: initialState.renderedItems },
      syncPrivateStore,
    ),
    { __unstableCollectionLookup: collectionLookup },
  );

  const sortItems = (renderedItems: T[]) => {
    const sortedItems = sortBasedOnDOMPosition(renderedItems, (i) => i.element);
    privateStore.setState("renderedItems", sortedItems);
    collection.setState("renderedItems", sortedItems);
  };

  const indexControlledItems = (items: T[]) => {
    if (items === collectionLookup.controlledItemsSource) return;
    collectionLookup.controlledItemsSource = items;
    controlledItems.clear();
    for (const item of items) {
      controlledItems.set(item.id, item);
    }
  };

  const setState: CollectionStore<T>["setState"] = (key, value) => {
    if (key !== "items") {
      collection.setState(key, value);
      return;
    }
    collection.setState("items", (items) => {
      const nextItems = applyState(value, items);
      if (nextItems === items) return items;
      collectionLookup.propagatedItems = nextItems;
      indexControlledItems(nextItems);
      return nextItems;
    });
  };

  setup(collection, () => init(privateStore));

  if (!syncPrivateStore) {
    // Returned Collection setters pre-index the shared lookup. Only the root
    // can receive items from a parent that doesn't share the lookup.
    subscribe(collection, ["items"], ({ items }) => {
      if (items === collectionLookup.propagatedItems) return;
      collectionLookup.propagatedItems = items;
      indexControlledItems(items);
    });

    // Use the private store to register items and then batch the changes to the
    // public store so we don't trigger multiple updates on the store when
    // adding multiple items.
    setup(privateStore, () => {
      return batch(privateStore, ["items"], ({ items }) => {
        collectionLookup.propagatedItems = items;
        collection.setState("items", items);
      });
    });
  }

  setup(privateStore, () => {
    return batch(privateStore, ["renderedItems"], (state) => {
      // Publish before the next paint. Waiting for an animation frame used to
      // let the browser paint the new items next to state derived from the
      // previous ones, such as the Combobox auto-selected item.
      // https://github.com/ariakit/ariakit/issues/3914
      //
      // sortItems writes back into this store, which can re-enter this listener
      // on the next microtask, so skip the array already published.
      if (state.renderedItems !== collection.getState().renderedItems) {
        sortItems(state.renderedItems);
      }

      if (typeof IntersectionObserver !== "function") return;

      // Scrolling fires this observer constantly, so its re-sort keeps the
      // animation frame that the publish above no longer needs.
      // https://github.com/ariakit/ariakit/issues/3285
      let firstRun = true;
      let raf = 0;

      const ioCallback: IntersectionObserverCallback = () => {
        if (firstRun) {
          // The IntersectionObserver callback is called synchronously the first
          // time. We just ignore it.
          firstRun = false;
          return;
        }
        cancelAnimationFrame(raf);
        raf = requestAnimationFrame(() => sortItems(state.renderedItems));
      };

      const root = getCommonParent(state.renderedItems);
      const observer = new IntersectionObserver(ioCallback, { root });

      for (const item of state.renderedItems) {
        if (!item.element) continue;
        observer.observe(item.element);
      }

      return () => {
        cancelAnimationFrame(raf);
        observer.disconnect();
      };
    });
  });

  const createMergeItem = (
    key: "items" | "renderedItems",
    cache: ItemIdCache<T>,
    lookup?: CollectionLookup<T>,
  ) => {
    const registeredItems = lookup?.registeredItems;
    const controlledItems = lookup?.controlledItems;
    return (item: T) => {
      const previousRegisteredItem = registeredItems?.get(item.id);
      const wasKnown =
        !!previousRegisteredItem || !!controlledItems?.has(item.id);
      let prevItem: T | undefined;
      privateStore.setState(key, (items) => {
        const shouldUseCache =
          !!cache.ids || (items.length >= itemIdCacheThreshold && !wasKnown);
        const ids = shouldUseCache ? getCachedItemIds(items, cache) : undefined;
        const index =
          ids && !ids.has(item.id)
            ? -1
            : items.findIndex(({ id }) => id === item.id);
        const nextItems = items.slice();
        if (index !== -1) {
          prevItem = items[index];
          const nextItem = { ...prevItem, ...item };
          nextItems[index] = nextItem;
          registeredItems?.set(item.id, nextItem);
        } else {
          nextItems.push(item);
          registeredItems?.set(item.id, item);
          ids?.add(item.id);
        }
        if (
          cache.ids ||
          (index === -1 && nextItems.length >= itemIdCacheThreshold)
        ) {
          setCachedItemIds(nextItems, cache, ids);
        }
        return nextItems;
      });
      // Same-ID registrations must clean up in reverse order: each cleanup
      // restores the item it replaced or removes the item it introduced.
      // https://github.com/ariakit/ariakit/pull/7286#discussion_r3853776498
      const unmergeItem = () => {
        if (registeredItems) {
          if (previousRegisteredItem) {
            registeredItems.set(item.id, previousRegisteredItem);
          } else {
            registeredItems.delete(item.id);
          }
        }
        privateStore.setState(key, (items) => {
          const ids = cache.ids ? getCachedItemIds(items, cache) : undefined;
          if (!prevItem) {
            const nextItems = items.filter(({ id }) => id !== item.id);
            ids?.delete(item.id);
            if (cache.ids) {
              setCachedItemIds(nextItems, cache, ids);
            }
            return nextItems;
          }
          const index = items.findIndex(({ id }) => id === item.id);
          if (index === -1) {
            return items;
          }
          const nextItems = items.slice();
          nextItems[index] = prevItem;
          if (cache.ids) {
            setCachedItemIds(nextItems, cache, ids);
          }
          return nextItems;
        });
      };
      return unmergeItem;
    };
  };

  const registerItem = createMergeItem("items", itemIdCache, collectionLookup);
  const mergeRenderedItem = createMergeItem(
    "renderedItems",
    renderedItemIdCache,
  );

  return {
    ...collection,

    setState,
    registerItem,
    renderItem: (item) => chain(registerItem(item), mergeRenderedItem(item)),

    item: (id) => {
      if (!id) return null;
      // Avoid an overlay lookup when there are no live registrations.
      if (!registeredItems.size) {
        return controlledItems.get(id) ?? null;
      }
      return registeredItems.get(id) ?? controlledItems.get(id) ?? null;
    },

    // @ts-expect-error Internal
    __unstablePrivateStore: privateStore,
  };
}

export interface CollectionStoreItem {
  /**
   * The id of the item.
   */
  id: string;
  /**
   * The item HTML element. This is automatically set when the item is rendered.
   */
  element?: HTMLElement | null;
}

export interface CollectionStoreState<
  T extends CollectionStoreItem = CollectionStoreItem,
> {
  /**
   * Lists all items along with their metadata. This state is automatically
   * updated when an item is registered or unregistered using the
   * [`registerItem`](https://ariakit.com/reference/use-collection-store#registeritem)
   * function.
   *
   * Live examples:
   * - [Command Menu with
   *   Tabs](https://ariakit.com/examples/dialog-combobox-tab-command-menu)
   */
  items: T[];
  /**
   * Lists all items, along with their metadata, in the exact order they appear
   * in the DOM. This state is automatically updated when an item is rendered or
   * unmounted using the
   * [`renderItem`](https://ariakit.com/reference/use-collection-store#renderitem)
   * function.
   */
  renderedItems: T[];
}

export interface CollectionStoreFunctions<
  T extends CollectionStoreItem = CollectionStoreItem,
> {
  /**
   * Registers an item in the collection. This function returns a cleanup
   * function that unregisters the item.
   * @example
   * const unregisterItem = store.registerItem({ id: "item-1" });
   * // on cleanup
   * unregisterItem();
   */
  registerItem: BivariantCallback<(item: T) => () => void>;
  /**
   * Renders an item in the collection. This function returns a cleanup function
   * that unmounts the item.
   * @example
   * const unrenderItem = store.renderItem({ id: "item-1" });
   * // on cleanup
   * unrenderItem();
   */
  renderItem: BivariantCallback<(item: T) => () => void>;
  /**
   * Gets an item by its id.
   *
   * Live examples:
   * - [Animated TabPanel](https://ariakit.com/examples/tab-panel-animated)
   * @example
   * const item = store.item("item-1");
   */
  item: (id: string | null | undefined) => T | null;
}

export interface CollectionStoreOptions<
  T extends CollectionStoreItem = CollectionStoreItem,
> extends StoreOptions<CollectionStoreState<T>, "items"> {
  /**
   * The default value for the
   * [`items`](https://ariakit.com/reference/collection-provider#items) state.
   * @default []
   */
  defaultItems?: CollectionStoreState<T>["items"];
}

export interface CollectionStoreProps<
  T extends CollectionStoreItem = CollectionStoreItem,
>
  extends CollectionStoreOptions<T>, StoreProps<CollectionStoreState<T>> {}

export interface CollectionStore<
  T extends CollectionStoreItem = CollectionStoreItem,
>
  extends CollectionStoreFunctions<T>, Store<CollectionStoreState<T>> {}
